// MDIO slave (IEEE 802.3 Clause 22 PHY management)
// ST(01) + OP(2) + PHYAD(5) + REGAD(5) + TA(2) + DATA(16), MSB first.
// Open-drain MDIO. A frame starts on ST (0 then 1) only after at least one
// idle/preamble 1 (preamble suppression down to one bit is accepted), so
// the tail of one frame can never be mistaken for the start of the next.
// Reads: the PHY drives the second turnaround bit low, then DATA[15:0].
// Auto-generated by gen_framework.py -- Apache-2.0
// ============================================================================
module MDIO_top #(
  parameter logic [4:0] PHY_ADDR = 5'h0C
)(
  input  logic        clk,
  input  logic        rst_n,
  inout  tri          mdio,
  input  logic        mdc,
  output logic        irq
);
  logic [15:0] regs [0:31];
  logic        mdc_s, mdc_d, mdio_s;
  logic        frame_act;
  logic        pre_ok;               // idle 1 seen since the last frame
  logic        st0;                  // ST first bit (0) seen after a 1
  logic [4:0]  cnt;
  logic [28:0] shift;
  logic        read_frame, read_match;
  logic [4:0]  regad_q;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      mdc_s <= 1'b0; mdc_d <= 1'b0; mdio_s <= 1'b1;
    end else begin
      mdc_s <= mdc; mdc_d <= mdc_s;
      mdio_s <= mdio;
    end
  end
  wire mdc_rise = mdc_s & ~mdc_d;

  // read drive window: the bit sampled by the master at the rising edge that
  // ends count value c is on the line while cnt==c (c=13: TA2 = 0,
  // c=14..29: DATA[15..0]).
  wire [15:0] rd_reg = regs[regad_q];
  wire drive_low = read_match && (cnt >= 5'd13)
                   && (cnt == 5'd13 || rd_reg[4'd13 - cnt[3:0]] == 1'b0);  // bit 29-cnt
  assign mdio = drive_low ? 1'b0 : 1'bz;
  assign irq  = frame_act && (cnt == 5'd29);

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      frame_act <= 1'b0; cnt <= '0; shift <= '0; pre_ok <= 1'b0; st0 <= 1'b0;
      read_frame <= 1'b0; read_match <= 1'b0; regad_q <= '0;
      for (int i = 0; i < 32; i++) regs[i] <= 16'h0000;
      regs[0] <= 16'h1140;              // PHY ID preset (like OpenCores eth phy)
    end else if (mdc_rise) begin
      if (!frame_act) begin
        if (mdio_s) begin
          if (st0) begin frame_act <= 1'b1; cnt <= '0; end   // ST = 01
          pre_ok <= !st0;
          st0    <= 1'b0;
        end else begin
          st0    <= pre_ok;             // a 0 directly after idle is ST[0]
          pre_ok <= 1'b0;
        end
      end else if (cnt == 5'd29) begin
        // frame complete: shift[28:0] holds first 29 frame bits, mdio_s is bit 30
        frame_act  <= 1'b0;
        read_frame <= 1'b0;
        read_match <= 1'b0;
        if (shift[28:27] == 2'b01 && shift[26:22] == PHY_ADDR) begin
          regs[shift[21:17]] <= {shift[14:0], mdio_s};   // write
        end
      end else begin
        shift <= {shift[27:0], mdio_s};
        cnt   <= cnt + 1'b1;
        if (cnt == 5'd1) begin
          read_frame <= (mdio_s == 1'b0) && (shift[0] == 1'b1); // OP == 10
        end
        if (cnt == 5'd6) begin
          read_match <= read_frame && ({shift[3:0], mdio_s} == PHY_ADDR);
        end
        if (cnt == 5'd11) begin
          regad_q <= {shift[3:0], mdio_s};
        end
      end
    end
  end

  // read-back mux for external register interface simplicity:
  // regs are internal; expose nothing else (Clause-22 PHY style)

endmodule
